import re

def trim(text: str) -> str:
    """
    Trims leading and trailing whitespace from a string and performs basic type inference.

    :param text: The string to clean.
    :return: The cleaned string.
    """
    return text.strip()

def type_infer(text: str) -> Any:
    """
    Infers the most likely type of the text (e.g., integer, float, string).

    :param text: The string to infer the type from.
    :return: The inferred type.
    """
    if text.isdigit():
        return int(text)
    try:
        return float(text)
    except ValueError:
        return text

